-- Platform Operations Console — Config Registry re-seed (data only; schema is 0615).
--
-- 1. Completes the inventory columns of the 50 seeded keys (applies_to_app list, env scope list).
-- 2. Registers 86 further keys discovered by reading the code and every .env file of both repositories
--    (names only: NO environment value or secret appears in this file).
-- 3. Copies the plain runtime flags from sys_ntf_runtime_cf into the registry (inside the database,
--    with SHA-256 fingerprints and change-log rows). sys_ntf_runtime_cf is retired in a later
--    migration once every reader uses the registry. The outbox secret is NOT copied (Vault, 0616).
-- 4. Flips is_wired for the HQ keys now read through ConfigResolverService.
--
-- Environment-specific values (this file runs on every database) are loaded separately by the local,
-- git-ignored script scripts/ops/seed-config-from-env.mjs, never by a migration.
-- Idempotent: re-running changes nothing that an operator edited (rows are only filled when empty).
BEGIN;

-- 1. Existing keys: applies_to_app list and env scope inventory (only filled when still at the default).
UPDATE public.sys_ops_config_cf AS c
   SET applies_to_app = v.apps::jsonb,
       env_var_scope_val = CASE WHEN c.env_var_scope_val = '[]'::jsonb THEN v.scopes::jsonb ELSE c.env_var_scope_val END,
       updated_at = now(),
       updated_info = '0617_ops_config_reseed'
  FROM (VALUES
  ('ntf.app.dispatch_via_hq', '[{"app":"TENANT_WEB","is_still_used":true},{"app":"HQ_API","is_still_used":true}]', '[{"scope":"TENANT_WEB","env_var_name":null,"is_it_there":"unknown","value":null,"fingerprint":null,"description":"Read by tenant web-admin from its host environment.","is_still_used":true},{"scope":"HQ_API","env_var_name":null,"is_it_there":"unknown","value":null,"fingerprint":null,"description":"Read by HQ platform-api from its host environment.","is_still_used":true}]'),
