  ('ntf.app.meta.wa_access_token', '[{"app":"TENANT_WEB","is_still_used":true}]', '[{"scope":"TENANT_WEB","env_var_name":null,"is_it_there":"unknown","value":null,"fingerprint":null,"description":"Read by tenant web-admin from its host environment.","is_still_used":true}]'),
