-- The scope list keeps the variable name each app uses; for the seeded keys that is the key's own env_var_name.
UPDATE public.sys_ops_config_cf AS c
   SET env_var_scope_val = (
         SELECT COALESCE(jsonb_agg(CASE WHEN e->>'env_var_name' IS NULL AND e->>'scope' <> 'DATABASE' THEN jsonb_set(e, '{env_var_name}', to_jsonb(c.env_var_name)) ELSE e END), '[]'::jsonb)
           FROM jsonb_array_elements(c.env_var_scope_val) AS e)
 WHERE c.updated_info = '0617_ops_config_reseed'
   AND c.env_var_name IS NOT NULL
   AND EXISTS (SELECT 1 FROM jsonb_array_elements(c.env_var_scope_val) AS e WHERE e->>'env_var_name' IS NULL AND e->>'scope' <> 'DATABASE');

-- 2. New keys (full data for every column; manage_via/guidance bilingual).
INSERT INTO public.sys_ops_config_cf (
  config_key, module, name, name2, description, description2, value_type, is_secret, is_encrypted, source_policy,
  env_var_name, is_bootstrap, is_wired, requires_restart, manage_via, guidance, guidance2, applies_to_app, env_var_scope_val,
  created_info, is_active, rec_status
