-- 3. HQ keys now read through ConfigResolverService (changes take effect within the 45 s cache, no restart).
UPDATE public.sys_ops_config_cf
   SET is_wired = true, requires_restart = false, updated_at = now(), updated_info = '0617_ops_config_reseed'
 WHERE config_key IN ('ntf.hq.resend.api_key', 'ntf.hq.resend.from_email', 'ntf.hq.twilio.account_sid', 'ntf.hq.twilio.auth_token', 'ntf.hq.twilio.sms_from', 'ntf.hq.twilio.whatsapp_from', 'ntf.hq.twilio.webhook_url', 'ntf.hq.twilio.content_cred_ref', 'ntf.hq.twilio.content_cred_ver', 'ntf.hq.meta.app_secret', 'ntf.hq.meta.wa_access_token', 'ntf.hq.meta.wa_phone_number_id', 'ntf.hq.fcm.server_key', 'ntf.hq.queue_enabled')
   AND (is_wired IS DISTINCT FROM true OR requires_restart IS DISTINCT FROM false);

-- 4. Copy runtime flags from sys_ntf_runtime_cf (values never leave the database; fingerprints computed here).
--    Only plain, non-bootstrap rows that hold no value yet and whose policy allows a stored value are filled.
CREATE TEMP TABLE tmp_ops_cfg_copy (config_key TEXT PRIMARY KEY, new_value TEXT NOT NULL, new_fp TEXT NOT NULL) ON COMMIT DROP;
INSERT INTO tmp_ops_cfg_copy (config_key, new_value, new_fp)
SELECT m.config_key, btrim(r.value), encode(sha256(convert_to(btrim(r.value), 'UTF8')), 'hex')
  FROM (VALUES
    ('whatsapp_fallback_email', 'ntf.app.whatsapp_fallback_email'),
    ('order_transition_notify', 'ntf.app.order_transition_notify'),
    ('outbox_inline_dispatch', 'ntf.app.outbox_inline_dispatch'),
    ('ntf_dispatch_via_hq', 'ntf.app.dispatch_via_hq'),
    ('ntf_hq_dispatch_url', 'ntf.app.hq_dispatch_url'),
    ('ntf_hq_route_dispatch_url', 'ntf.app.hq_route_dispatch_url'),
    ('resend_from_email', 'ntf.app.resend_from_email'),
    ('twilio_sms_from', 'ntf.app.twilio_sms_from'),
    ('twilio_whatsapp_from', 'ntf.app.twilio_whatsapp_from'),
    ('wa_sandbox_content_sid', 'ntf.app.wa_sandbox_content_sid'),
    ('wa_sandbox_to_phone', 'ntf.app.wa_sandbox_to_phone'),
    ('wa_use_sandbox_template', 'ntf.app.wa_use_sandbox_template'),
    ('base_url', 'ntf.app.base_url')
  ) AS m(runtime_key, config_key)
  JOIN public.sys_ntf_runtime_cf r ON r.key = m.runtime_key AND r.is_active AND r.rec_status = 1
  JOIN public.sys_ops_config_cf c ON c.config_key = m.config_key AND c.rec_status = 1 AND c.is_active
 WHERE btrim(COALESCE(r.value, '')) <> ''
   AND NOT c.is_encrypted AND NOT c.is_bootstrap AND c.source_policy <> 'ENV_ONLY'
   AND c.db_value IS NULL AND c.db_value_enc IS NULL;

UPDATE public.sys_ops_config_cf AS c
   SET db_value = t.new_value,
       db_value_fingerprint = t.new_fp,
       value_updated_at = now(),
       value_updated_by = 'migration:0617',
       updated_info = '0617_ops_config_reseed: copied from sys_ntf_runtime_cf'
  FROM tmp_ops_cfg_copy t
 WHERE c.config_key = t.config_key;

INSERT INTO public.sys_ops_config_chg_log (config_key, action, actor, old_fingerprint, new_fingerprint, created_info)
SELECT t.config_key, 'SET', 'migration:0617', NULL, t.new_fp, '0617 copy from sys_ntf_runtime_cf'
  FROM tmp_ops_cfg_copy t;

COMMIT;
